#!/bin/sh
set -e
here="$(cd "$(dirname "$0")" && pwd)"
. "$here/../toolchain.sh"

fetch_llvm
src="$sources/llvm-project-22.1.8"
cp "$src/libcxx/LICENSE.TXT" "$here/LICENSE"
build="$src/build-libcxx-wasm32-wasip1-threads"

rm -rf "$build"
output wasm32-wasip1-threads
mkdir -p "$build/Platform"
echo 'set(WASI 1)' > "$build/Platform/WASI.cmake"
cmake -S "$src/runtimes" -B "$build" -G Ninja -Wno-dev \
    -DCMAKE_SYSTEM_NAME=WASI -DCMAKE_SYSTEM_VERSION=1 -DCMAKE_SYSTEM_PROCESSOR=wasm32 -DCMAKE_MODULE_PATH="$build" \
    -DCMAKE_BUILD_TYPE=Release -DCMAKE_C_FLAGS_RELEASE="-O2 -DNDEBUG" -DCMAKE_CXX_FLAGS_RELEASE="-O2 -DNDEBUG" \
    -DCMAKE_C_COMPILER="$llvm/clang" -DCMAKE_CXX_COMPILER="$llvm/clang++" \
    -DCMAKE_AR="$llvm/llvm-ar" -DCMAKE_RANLIB="$llvm/llvm-ranlib" -DCMAKE_NM="$llvm/llvm-nm" \
    -DCMAKE_CXX_ARCHIVE_CREATE="<CMAKE_AR> --format=gnu qc <TARGET> <LINK_FLAGS> <OBJECTS>" \
    -DCMAKE_C_COMPILER_WORKS=ON -DCMAKE_CXX_COMPILER_WORKS=ON -DLLVM_COMPILER_CHECKED=ON \
    -DCMAKE_C_LINKER_DEPFILE_SUPPORTED=OFF -DCMAKE_CXX_LINKER_DEPFILE_SUPPORTED=OFF -DCMAKE_TRY_COMPILE_TARGET_TYPE=STATIC_LIBRARY \
    -DCMAKE_SYSROOT="$wasm_sysroot" \
    -DCMAKE_C_FLAGS="$wasm_cflags" -DCMAKE_CXX_FLAGS="$wasm_cflags" \
    -DCMAKE_INSTALL_PREFIX="$out" -DCMAKE_POSITION_INDEPENDENT_CODE=OFF -DUNIX=ON \
    -DLLVM_ENABLE_RUNTIMES="libcxx;libcxxabi" -DLLVM_INCLUDE_TESTS=OFF \
    -DLIBCXX_ENABLE_THREADS=ON -DLIBCXX_HAS_PTHREAD_API=ON -DLIBCXX_HAS_EXTERNAL_THREAD_API=OFF -DLIBCXX_HAS_WIN32_THREAD_API=OFF \
    -DLIBCXX_ENABLE_SHARED=OFF -DLIBCXX_ENABLE_EXCEPTIONS=OFF -DLIBCXX_ENABLE_FILESYSTEM=OFF -DLIBCXX_ENABLE_ABI_LINKER_SCRIPT=OFF \
    -DLIBCXX_CXX_ABI=libcxxabi -DLIBCXX_HAS_MUSL_LIBC=ON -DLIBCXX_ABI_VERSION=2 \
    -DLIBCXX_INCLUDE_TESTS=OFF -DLIBCXX_INCLUDE_BENCHMARKS=OFF \
    -DLIBCXXABI_ENABLE_EXCEPTIONS=OFF -DLIBCXXABI_ENABLE_SHARED=OFF -DLIBCXXABI_SILENT_TERMINATE=ON -DLIBCXXABI_ENABLE_THREADS=ON -DLIBCXXABI_HAS_PTHREAD_API=ON \
    -DLIBCXXABI_HAS_EXTERNAL_THREAD_API=OFF -DLIBCXXABI_HAS_WIN32_THREAD_API=OFF -DLIBCXXABI_USE_LLVM_UNWINDER=OFF
cmake --build "$build" --target install-cxx install-cxxabi >/dev/null
rm -f "$out/lib/libc++experimental.a" "$out/lib/libc++.modules.json"
publish
